const translations: Record<string, TranslationSet> = {
  ...instituteDashboardTranslations,
  ...baseTranslations,
  ...additionalTranslations,
};

export function translateUiText(language: Language, englishText: string): string {
  if (language === 'English') return englishText;
  return translations[englishText]?.[language] ?? englishText;
}
